function saveApi(kind){var body={},input;if(kind==='openai'){input=$('openaiApiKey');body.openaiApiKey=input.value}else if(kind==='anthropic'){input=$('anthropicApiKey');body.anthropicApiKey=input.value}else if(kind==='x'){input=$('xBearerToken');body.xBearerToken=input.value}else{input=$('zeroxApiKey');body.zeroxApiKey=input.value;body.iatbFeeRecipient=$('iatbFeeRecipient').value.trim();body.swapBridgeRpc={ethereum:$('rpcEthereum').value.trim(),arbitrum:$('rpcArbitrum').value.trim(),polygon:$('rpcPolygon').value.trim(),bnb:$('rpcBnb').value.trim(),base:$('rpcBase').value.trim()}}if(kind!=='zerox'&&!input.value.trim())return apiMsg(kind,'Saisissez une clé ou un token.',false);if(kind==='zerox'&&!input.value.trim()&&!(state.legacy&&state.legacy.zeroxConfigured))return apiMsg(kind,'Saisissez la clé API 0x.',false);apiMsg(kind,'Enregistrement…',false);api('/api/settings/apis',{method:'POST',body:body}).then(function(){input.value='';apiMsg(kind,'✓ Configuration enregistrée.',true);return loadLegacy()}).then(renderApi).catch(function(e){apiMsg(kind,'Erreur : '+e.message,false)})}
