function loadIndicators(){return Promise.all([api('/indicator-api/health'),api('/indicator-api/api/indicators')]).then(function(a){var h=a[0],x=a[1];indicatorItems=x.items||[];$('indicatorState').textContent=h.ok?'ONLINE':'OFFLINE';var st=x.status||{};$('indicatorSummary').innerHTML='<div><small>TOTAL</small><b>'+(st.total||indicatorItems.length)+'</b></div><div><small>BUILTIN</small><b>'+(st.builtIn||0)+'</b></div><div><small>CUSTOM</small><b>'+(st.custom||0)+'</b></div><div><small>QUARANTAINE</small><b>'+(st.quarantine||0)+'</b></div>';renderIndicators()}).catch(function(e){$('indicatorState').textContent='INDISPONIBLE';$('indicatorMsg').textContent='Indicator Engine : '+e.message})}
function renderIndicators(){var q=String($('indicatorSearch').value||'').toLowerCase(),fl=$('indicatorFilter').value,a=indicatorItems.filter(function(x){return(fl==='ALL'||x.kind===fl)&&(!q||(x.id+' '+x.name+' '+(x.category||'')).toLowerCase().indexOf(q)>=0)});$('indicatorList').innerHTML=a.length?a.map(function(x){return'<div class="indicatorItem"><div class="indicatorMark '+(x.kind==='Custom'?'custom':'builtin')+'">∿</div><div class="indicatorMain"><b>'+x.name+'</b><code>'+x.id+'</code><small>'+(x.category||'indicator')+' · '+(x.operation||'IIL/IR')+' · v'+(x.version||'--')+'</small></div><span class="indicatorKind '+(x.kind==='Custom'?'custom':'')+'">'+x.kind+'</span><button class="ghost indicatorOpen" data-ind-open="'+x.id+'">Voir</button>'+(x.kind==='Custom'?'<button class="danger indicatorDelete" data-ind-delete="'+x.id+'">Supprimer</button>':'')+'</div>'}).join(''):'<div class="emptyVault">Aucun indicateur correspondant.</div>';document.querySelectorAll('[data-ind-open]').forEach(function(n){n.onclick=function(){api('/indicator-api/api/definition?id='+encodeURIComponent(n.dataset.indOpen)).then(function(x){$('indicatorEditor').value=x.definition&&x.definition.language&&x.definition.language.source?x.definition.language.source:JSON.stringify(x.definition,null,2);$('indicatorEditorMsg').textContent=x.editable?'Custom chargé en lecture. Pour le remplacer, supprimez-le puis recréez-le.':'BuiltIn protégé · définition affichée en lecture.'})}});document.querySelectorAll('[data-ind-delete]').forEach(function(n){n.onclick=function(){if(!confirm('Supprimer l’indicateur Custom '+n.dataset.indDelete+' ?'))return;api('/indicator-api/api/custom/delete',{method:'POST',body:{id:n.dataset.indDelete}}).then(function(){$('indicatorMsg').textContent='✓ Indicateur supprimé.';loadIndicators()}).catch(function(e){$('indicatorMsg').textContent='Erreur : '+e.message})}})}
function importIndicatorJson(file){if(!file)return;if(file.size>131072){$('indicatorEditorMsg').textContent='Import refusé : JSON supérieur à 128 Ko.';return}var reader=new FileReader();reader.onerror=function(){$('indicatorEditorMsg').textContent='Import impossible : lecture du fichier échouée.'};reader.onload=function(){var d;try{d=JSON.parse(String(reader.result||''));}catch(e){$('indicatorEditorMsg').textContent='Import refusé : JSON invalide.';return}if(!d||typeof d!=='object'||Array.isArray(d)){$('indicatorEditorMsg').textContent='Import refusé : définition JSON invalide.';return}$('indicatorEditorMsg').textContent='Validation de '+(d.name||d.id||file.name)+'…';api('/indicator-api/api/definition/validate',{method:'POST',body:{definition:d}}).then(function(v){if(v.ok===false)throw new Error((v.errors||[]).join(' | ')||'INDICATOR_DEFINITION_INVALID');if(!confirm('Importer l’indicateur '+(d.name||d.id)+' dans le Registry ?'))return;return api('/indicator-api/api/definition/create',{method:'POST',body:{definition:d}}).then(function(x){$('indicatorEditor').value=d.language&&d.language.source?d.language.source:JSON.stringify(d,null,2);$('indicatorEditorMsg').textContent='✓ '+x.id+' importé, validé et chargé dans le Registry.';loadIndicators()})}).catch(function(e){$('indicatorEditorMsg').textContent='Import refusé : '+e.message})};reader.readAsText(file)}
function bindIndicators(){$('refreshIndicators').onclick=loadIndicators;$('indicatorSearch').oninput=renderIndicators;$('indicatorFilter').onchange=renderIndicators;$('newIndicator').onclick=function(){$('indicatorEditor').value=indicatorTemplate();$('indicatorEditorMsg').textContent='Nouveau brouillon IIL.'};$('importIndicator').onclick=function(){$('indicatorImportFile').value='';$('indicatorImportFile').click()};$('indicatorImportFile').onchange=function(){importIndicatorJson(this.files&&this.files[0])};$('validateIndicator').onclick=function(){$('indicatorEditorMsg').textContent='Validation…';api('/indicator-api/api/language/validate',{method:'POST',body:{source:$('indicatorEditor').value}}).then(function(x){$('indicatorEditorMsg').textContent='✓ IIL valide · '+x.definition.id+' · prêt à créer.'}).catch(function(e){$('indicatorEditorMsg').textContent='Erreur IIL : '+e.message})};$('saveIndicator').onclick=function(){if(!confirm('Créer cet indicateur Custom dans le Registry ?'))return;api('/indicator-api/api/language/create',{method:'POST',body:{source:$('indicatorEditor').value}}).then(function(x){$('indicatorEditorMsg').textContent='✓ '+x.id+' créé et chargé dans le Registry.';loadIndicators()}).catch(function(e){$('indicatorEditorMsg').textContent='Erreur : '+e.message})};$('indicatorEditor').value=indicatorTemplate()}
function loadFundamental(){Promise.all([api('/fundamental-api/health'),api('/fundamental-api/api/summary'),api('/fundamental-api/api/feeds')]).then(function(a){var h=a[0],sm=a[1].summary||{},feeds=a[2].feeds||[];$('fundState').textContent=h.ok?'ONLINE':'OFFLINE';$('fundSummary').innerHTML='<div><b>'+(sm.sourcesEnabled||0)+'</b><small>Sources actives</small></div><div><b>'+(sm.feedsEnabled||0)+'</b><small>Flux actifs</small></div><div><b>'+(sm.raw24h||0)+'</b><small>Publications · 24 h</small></div><div><b>'+(h.ai&&h.ai.configured?'PRÊTE':'NON CONFIGURÉE')+'</b><small>Synthèse IA</small></div>';renderFundFeeds(feeds)}).catch(function(e){$('fundState').textContent='INDISPONIBLE';$('fundMsg').textContent='Fundamental Engine : '+e.message});try{var x=JSON.parse(localStorage.getItem('iatb_fund_prefs')||'{}');fundPrefs.language=x.language||'fr';fundPrefs.window=x.window||'24H';fundPrefs.limit=+x.limit||28}catch(e){}$('fundLanguage').value=fundPrefs.language;$('fundWindow').value=fundPrefs.window;$('fundLimit').value=fundPrefs.limit}
