function crCalc(rows,price,model){if(price.input===null||price.output===null)return null;var a=rows.filter(function(x){return !model||x.model===model});if(!a.length)return 0;return a.reduce(function(s,x){return s+((x.input||0)*price.input+(x.output||0)*price.output)/1000000},0)}
