function renderCredits(){if(!creditData)return;var a=creditData.events||[],p=creditData.pricing||{},rate=p.eurPerUsd||null;['openai','anthropic'].forEach(function(k){var rows=a.filter(function(x){return x.provider===k}),total=rows.reduce(function(s,x){return s+(x.total||0)},0),cfg=p[k]||{},cost=crCalc(rows,cfg,cfg.model);$(k==='openai'?'crOpenTokens':'crAnthTokens').textContent=crFmt(total);$(k==='openai'?'crOpenCost':'crAnthCost').textContent=cost===null?'Coût non configuré':crMoney(cost,rate)+' (estimation)'});$('creditOpenModel').value=p.openai&&p.openai.model||'';$('creditAnthModel').value=p.anthropic&&p.anthropic.model||'';[['OpenIn','openai','input'],['OpenOut','openai','output'],['AnthIn','anthropic','input'],['AnthOut','anthropic','output']].forEach(function(x){var v=p[x[1]]&&p[x[1]][x[2]];$('credit'+x[0]).value=v===null||v===undefined?'':v});$('creditFx').value=p.eurPerUsd||'';drawCredits()}
